import { expect, test } from './browser-test.ts';
import { exportedSnapshot, loadTimedBoard } from './game-fixture.ts';
import { PREFERENCES_KEY } from '../src/game/session/storage.ts';

test('editing and clearing a deal name preserves progress and the active mismatch deadline', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('.card').nth(0).click();
  await page.locator('.card').nth(1).click();
  await page.clock.runFor(175);
  const before = await exportedSnapshot(page);
  await page.locator('summary').click();
  const name = page.getByRole('textbox', { name: 'Deal name', exact: true });
  await expect(name).toHaveValue('');
  await expect(name).toHaveAttribute('maxlength', '40');
  await name.fill('🃏'.repeat(20) + 'x');
  await expect(name).toHaveValue('🃏'.repeat(20));
  await name.fill('  Café 🃏  ');
  const exportButton = page.getByRole('button', { name: 'Export snapshot', exact: true });
  await exportButton.click();
  await expect(exportButton).toBeFocused();
  const text = await page.getByLabel('Snapshot JSON', { exact: true }).inputValue();
  expect(text).toContain('\n');
  expect(JSON.parse(text)).toEqual({ ...before, version: 2, name: '  Café 🃏  ' });
  await name.fill('');
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toEqual(before);
  await page.clock.runFor(624);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  await page.clock.runFor(1);
  await expect(page.locator('.card.closed')).toHaveCount(16);
  expect((await exportedSnapshot(page)).elapsedMs).toBe(800);
});

test('names clear on every deal reset and never enter saved preferences', async ({
  page,
  gameURL,
}) => {
  await loadTimedBoard(page, gameURL);
  await page.locator('summary').click();
  const name = page.getByLabel('Deal name', { exact: true });
  for (const action of ['New Game', 'Restart', 'Grid size', 'Load board']) {
    await name.fill('My saved deal');
    if (action === 'Grid size') {
      await page.getByLabel(action, { exact: true }).selectOption('6');
    } else {
      if (action === 'Load board')
        await page.getByLabel('Board code', { exact: true }).fill('np1-4-1');
      const button = page.getByRole('button', { name: action, exact: true });
      await button.click();
      await expect(button).toBeFocused();
    }
    await expect(name).toHaveValue('');
  }
  await name.fill('Private in-memory name');
  const preferences = await page.evaluate((key) => localStorage.getItem(key), PREFERENCES_KEY);
  expect(preferences).not.toBeNull();
  expect(preferences).not.toContain('name');
  await page.reload();
  await page.locator('summary').click();
  await expect(name).toHaveValue('');
  await page.locator('summary').click();
  const snapshot = await exportedSnapshot(page);
  expect(snapshot.version).toBe(1);
  expect(Object.hasOwn(snapshot, 'name')).toBe(false);
});
import { expect, test } from './browser-test.ts';
import { exportedSnapshot, loadTimedBoard } from './game-fixture.ts';
import type { Page } from '@playwright/test';

// Deliberately use a different field order from the game's export, including its selection.
const PROGRESS = {
  selection: { remainingMs: 300, second: 2, kind: 'mismatch', first: 1 },
  elapsedMs: 1500,
  moves: 2,
  matched: [11, 0],
  boardCode: 'np1-4-1',
  started: true,
  version: 1,
};

async function pasteSnapshot(page: Page, snapshot: Record<string, unknown>): Promise<void> {
  await page.getByLabel('Snapshot JSON', { exact: true }).fill(JSON.stringify(snapshot));
  await page.getByRole('button', { name: 'Load snapshot', exact: true }).click();
}

test('pasted snapshots load in either version with restored names and exact paused progress', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('summary').click();
  const name = page.getByLabel('Deal name', { exact: true });
  await name.fill('Replace this name');
  for (const snapshot of [PROGRESS, { ...PROGRESS, name: '  Café 🃏  ', version: 2 }]) {
    await pasteSnapshot(page, snapshot);
    await expect(page.getByRole('button', { name: 'Load snapshot', exact: true })).toBeFocused();
    const savedName = 'name' in snapshot ? snapshot.name : '';
    await expect(name).toHaveValue(savedName);
    await expect(page.locator('.load-notice')).toHaveText(
      'Loaded snapshot. Select Resume to continue.',
    );
    await name.fill('Edited while paused');
    await page.locator('.card').nth(3).click();
    await page.keyboard.press('Enter');
    await page.clock.runFor(1000);
    await page.locator('summary').click();
    expect(await exportedSnapshot(page)).toEqual({
      ...PROGRESS,
      version: 2,
      name: 'Edited while paused',
      matched: [0, 11],
    });
    await page.getByRole('button', { name: 'Resume', exact: true }).click();
    await expect(page.locator('.card').nth(3)).toBeFocused();
    await page.clock.runFor(299);
    await expect(page.locator('.card.revealed')).toHaveCount(2);
    await page.clock.runFor(1);
    await expect(page.locator('.card.revealed')).toHaveCount(0);
    await page.locator('summary').click();
  }
});

test('invalid named drafts keep the game, name, pause and draft for correction', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('summary').click();
  await pasteSnapshot(page, { ...PROGRESS, name: 'Keep this', version: 2 });
